import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.CurrentStructureFeature{CurrentFeature:
# "minecraft:ancient_city"}
ANCIENT_CITY = bytes.fromhex("166d696e6563726166743a616e6369656e745f63697479")

# generated by gophertunnel b8bd735:
# packet.CurrentStructureFeature{CurrentFeature: ""}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# packet.CurrentStructureFeature{CurrentFeature: strings.Repeat("a", 200)}
LONG_NAME = bytes.fromhex(
    "c80161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "61616161616161616161"
)

GOLDENS = [
    pytest.param(
        v2225.CurrentStructureFeaturePacket(current_structure_feature="minecraft:ancient_city"),
        ANCIENT_CITY,
        id="ancient-city",
    ),
    pytest.param(v2225.CurrentStructureFeaturePacket(), EMPTY, id="empty"),
    pytest.param(v2225.CurrentStructureFeaturePacket(current_structure_feature="a" * 200), LONG_NAME, id="long-name"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_current_structure_feature_is_packet_314(version):
    assert version.PACKETS[314] is version.CurrentStructureFeaturePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_current_structure_feature_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_current_structure_feature_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
